import{_ as e,o as a,c as d,ag as i}from"./chunks/framework.C9sp7nFj.js";const m=JSON.parse('{"title":"SetSimDIEdge 设置虚拟数字量输入边沿","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/4. IO 指令/SetSimDIEdge.md","filePath":"3. 指令/4. IO 指令/SetSimDIEdge.md","lastUpdated":1778862643000}'),s={name:"3. 指令/4. IO 指令/SetSimDIEdge.md"};function r(n,t,o,h,l,p){return a(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="setsimdiedge-设置虚拟数字量输入边沿" tabindex="-1">SetSimDIEdge 设置虚拟数字量输入边沿 <a class="header-anchor" href="#setsimdiedge-设置虚拟数字量输入边沿" aria-label="Permalink to &quot;SetSimDIEdge 设置虚拟数字量输入边沿&quot;">​</a></h1><p>该指令用于通过指令强制设置某个虚拟数字量输入端口（SimDI）的边沿信号状态。它允许程序在逻辑运行过程中，模拟虚拟信号的瞬时跳变触发（上升沿或下降沿），常用于多线程同步或仿真测试场景。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p><code>SetSimDIEdge (SIMDIN, EDGETYPE, VALUE)</code></p><p><code>SetSimDIEdge (虚拟数字量输入端口, 边沿类型, 强制值)</code></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>SIMDIN</td><td>SimDI</td><td>待强制边沿信号的目标虚拟数字量输入变量</td><td>必填</td></tr><tr><td>EDGETYPE</td><td>enum</td><td>边沿类型（<code>&quot;riseEdge&quot;</code>：上升沿，<code>&quot;fallEdge&quot;</code>：下降沿）</td><td>必填</td></tr><tr><td>VALUE</td><td>int 或 INT 变量</td><td>要在指定端口强制的边沿信号状态值（通常为 1 或 0）</td><td>必填</td></tr></tbody></table><hr><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><p><strong>示例 1：</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetSimDIEdge</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (SimDI9, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;riseEdge&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>强制 <strong>SimDI9</strong> 端口的上升沿信号为 <strong>1</strong> 状态。即使该虚拟端口的电平没有实际物理变化，此指令也会触发所有监听该端口上升沿的逻辑分支。</p>',13)])])}const E=e(s,[["render",r]]);export{m as __pageData,E as default};
